export type SiteKind = 'Web form' | 'REST API' | 'Portal';

/** A Visualforce page, Aura bundle or LWC, with the Apex controllers it calls itself. */
export interface SiteComponent {
  name: string;
  controllers: string[];
}

/** A public Salesforce Site, generated by scripts/classify-sites.mjs. */
export interface SiteInfo {
  /** Site name, taken from its guest user profile ("<name> Profile"). */
  name: string;
  profile: string;
  /** Web form: VF page + Aura + LWC. REST API: Apex REST endpoints only. Portal: the Experience Cloud portals. */
  kind: SiteKind;
  vfPages: SiteComponent[];
  /** Aura apps and components loaded by the site's pages. */
  aura: SiteComponent[];
  lwc: SiteComponent[];
  /** Apex classes enabled on the guest profile plus those called by the site's components. Tests excluded. */
  apex: string[];
  /** Subset of `apex` that the site's components call but the guest profile does not enable. */
  notGranted: string[];
  /** Apex REST endpoints exposed through the site. */
  rest: { cls: string; path: string }[];
}

export const SITE_KINDS: { value: SiteKind; color: string; hint: string }[] = [
  { value: 'Web form', color: '#2563eb', hint: 'A public form: Visualforce page, Aura app, LWC and Apex.' },
  { value: 'REST API', color: '#ea580c', hint: 'Apex REST endpoints that outside systems call through a site.' },
  { value: 'Portal', color: '#059669', hint: 'Customer and channel partner portals.' },
];
